 const unit=alive(g,'india').find(u=>selected.includes(u.id));const contact=pending?g.contacts.india[pending]:null;const scenario=SCENARIOS[g.settings.scenario];const friends=alive(g,'india');const contacts=Object.values(g.contacts.india);const currentContacts=contacts.filter(c=>g.time-c.seen<1);const baseList=g.units.filter(u=>g.originalBases.includes(u.id));
 useEffect(()=>{const el=svg.current;if(!el)return;const update=()=>{const rect=el.getBoundingClientRect();const pixelsPerUnit=el.getScreenCTM()?.a??rect.width/view.w;setSpriteSize(Math.max(.055,Math.min(2,1/Math.max(.1,pixelsPerUnit))));};update();const observer=new ResizeObserver(update);observer.observe(el);return()=>observer.disconnect();},[view.w,view.h,scene3d]);
