 useEffect(()=>{if(!muted&&g.shots.length&&g.shots[g.shots.length-1].id!==lastSound.current){lastSound.current=g.shots[g.shots.length-1].id;try{const ctx=sound.current;if(ctx){const osc=ctx.createOscillator(),gain=ctx.createGain();osc.type='sine';osc.frequency.setValueAtTime(400,ctx.currentTime);osc.frequency.exponentialRampToValueAtTime(90,ctx.currentTime+.12);gain.gain.setValueAtTime(.05,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.12);osc.connect(gain);gain.connect(ctx.destination);osc.start();osc.stop(ctx.currentTime+.13);}}catch{}}},[frame,muted,g.shots]);
